import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../../data/models/loan.dart';
import '../../../data/repositories/group_repository.dart';
import '../../widgets/app_drawer.dart';
class LoansScreen extends StatelessWidget{const LoansScreen({super.key});@override Widget build(BuildContext context){final repo=context.read<GroupRepository>();return Scaffold(appBar:AppBar(title:const Text('Loans')),drawer:const AppDrawer(),floatingActionButton:FloatingActionButton(onPressed:()=>_add(context,repo),child:const Icon(Icons.add)),body:ListView(padding:const EdgeInsets.all(16),children:[const Text('Loan History',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),StreamBuilder(stream:repo.loans(),builder:(c,s)=>Column(children:(s.data??[]).map((x)=>Card(child:ListTile(title:Text(x.toString()),subtitle:Text('Digital record')))).toList()))]));} void _add(BuildContext context,GroupRepository repo){final member=TextEditingController();final amount=TextEditingController();final type=TextEditingController();showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Loan Application'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:member,decoration:const InputDecoration(labelText:'Member / Description / Agenda')),TextField(controller:amount,decoration:const InputDecoration(labelText:'Amount / Decisions'),keyboardType:TextInputType.number),TextField(controller:type,decoration:const InputDecoration(labelText:'Type'))]),actions:[FilledButton(onPressed:(){repo.addLoan(Loan(id:'',memberId:member.text,amount:double.tryParse(amount.text)??0,interest:10,issueDate:DateTime.now(),dueDate:DateTime.now().add(const Duration(days:30)),balance:(double.tryParse(amount.text)??0)*1.10));Navigator.pop(context);},child:const Text('Save'))]));}}
